  Lemma mb_rem_intro : forall s m LB bb es out insz outpos outend,
    MBraw m bb es out insz outpos outend -> MBufOwn LB es -> hs_RHEAP H s LB m ->
    exists bs, map blk_addr bs = map fst es /\ mb_rem m LB (bb + 8) bs es /\ List.NoDup (map blk_id bs)
               /\ (forall b, In b bs -> In b LB /\ mbowned es b).
  Proof.
    intros s m LB bb es out insz outpos outend (ls & H0 & H1 & DL & LC & EL & AOK) OWN HP.
    pose proof (dl_N _ _ _ DL) as ND0. pose proof (mb_L_nodup _ _ _ DL) as NDE.
    assert (G : forall L2 L1, es = L1 ++ L2 ->
      exists bs, map blk_addr bs = map fst L2 /\ mb_rem m LB (bb + 8) bs es /\ List.NoDup (map blk_id bs)
                 /\ (forall b, In b bs -> In b LB /\ mbowned es b)).
    { induction L2 as [|[y sz] L2 IH]; intros L1 EL'.
      - exists []. split; [reflexivity|]. split; [intros A b B E; destruct A; discriminate|]. split; [constructor|]. intros b [].
      - destruct (IH (L1 ++ [(y, sz)]) ltac:(rewrite EL', <- app_assoc; reflexivity)) as (bs' & MAP & REM & ND & SUB).
        assert (INy : In (y, sz) es). { rewrite EL'. apply in_app_iff. right. left. reflexivity. }
        destruct (OWN y sz INy) as [p INp].
        exists ((p, y, mb_block_size sz) :: bs'). split; [cbn; rewrite MAP; reflexivity|]. split.
        { intros A b B E. destruct A as [|a A'].
          - cbn in E. injection E as <- <-. cbn [blk_addr blk_size fst snd]. split; [exact INp|].
            destruct (MBElems_lookup _ _ _ _ EL INy) as [junk C].
            exists sz, (wz (llast (bb + 8) (map fst L1))). split; [exact INy|]. split; [reflexivity|]. split.
            + rewrite MAP. exact (mb_elem_node m bb es L1 L2 y sz ls DL LC EL').
            + apply (proj1 (rw_cells_app usegs m (y + 16) [C8 (wz sz)] [CB (Z.to_nat sz) junk])). exact C.
          - cbn in E. injection E as Ea E'. exact (REM A' b B E'). }
        split.
        { cbn. constructor; [| exact ND]. intros K. apply in_map_iff in K. destruct K as (b' & Eb' & Hb').
          destruct (SUB b' Hb') as [INb' _].
          assert (Eq : b' = (p, y, mb_block_size sz)) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact INb'| exact INp| exact Eb']).
          subst b'. assert (Iy : In y (map blk_addr bs')) by (apply in_map_iff; exists (p, y, mb_block_size sz); split; [reflexivity| exact Hb']).
          rewrite MAP in Iy. rewrite EL', map_app in NDE. cbn [map fst] in NDE.
          apply list.NoDup_app in NDE. destruct NDE as (_ & _ & NDL). apply list.NoDup_cons in NDL. destruct NDL as [NI _].
          apply NI. apply list_elem_of_In. exact Iy. }
        intros b [<-|Hb]; [| exact (SUB b Hb)]. split; [exact INp|]. exists sz. cbn [blk_addr blk_size fst snd]. split; [exact INy| reflexivity]. }
    exact (G es [] eq_refl).
  Qed.

