(* [comment removed for export] *)
Definition powned (em : gmap Z elt) (h : hdrv) (es : list mbe) (b : block) : Prop := bfowned em h b \/ mbowned es b.

(* [comment removed for export] *)
Definition BodyDisj (em : gmap Z elt) (h : hdrv) (es : list mbe) : Prop :=
  forall x s, In (x, s) es -> em !! x = None /\ (1 <= hv_ml h -> x <> hv_mp h) /\ (1 <= hv_tl h -> x <> hv_tp h).

