(* [comment removed for export] *)
Definition parser_dtor_X (P : Z) : list (Z * Z) := [(P, P + 8); (P + 40, P + 48); (P + 128, P + 160)]%Z.

(* [comment removed for export] *)
Lemma FieldsC_xpres : forall LB SP X m m' Fa S L ns ls em,
  FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> xpres LB SP X m m' -> SP <= Fa ->
  Forall (fun iv : Z * Z => Fa + 48 <= fst iv \/ snd iv <= Fa) X ->
  (forall e d, em !! e = Some d -> Forall (fun iv : Z * Z => e + esize d <= fst iv \/ snd iv <= e) X) ->
  FieldsC m' Fa S L ns ls em.
Proof.
  intros LB SP X m m' Fa S L ns ls em FC OWN XP LE XB XE.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE' & EOK & HH & HB & AL).
  assert (XSUB : forall a n a' n', Forall (fun iv : Z * Z => a + n <= fst iv \/ snd iv <= a) X -> a <= a' -> a' + n' <= a + n ->
                 Forall (fun iv : Z * Z => a' + n' <= fst iv \/ snd iv <= a') X).
  { intros a n a' n' F L1 L2. eapply Forall_impl; [| exact F]. intros [u v]; cbn; lia. }
  assert (ESUB : forall e d a' n', em !! e = Some d -> e <= a' -> a' + n' <= e + esize d -> xclient_range LB SP X a' n').
  { intros e d a' n' Ld L1 L2. destruct (OWN e d Ld) as [p [INp _]]. split.
    - right; right. exists (p, e, esize d). split; [exact INp| cbn; lia].
    - eapply XSUB; [exact (XE e d Ld)| lia| lia]. }
  split.
  { intros a nd La. destruct (NC a nd La) as [WF [pad C]]. split; [exact WF|]. exists pad.
    eapply xpres_rw_cells; [exact XP| exact C|]. rewrite NodeCells_size.
    destruct (FieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P0 & _ & R)].
    - split; [left; lia| eapply XSUB; [exact XB| lia| cbn; lia]].
    - pose proof (esize_ge d). eapply ESUB; [exact Ld| lia| cbn; lia]. }
  split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|].
    eapply xpres_rw_cells; [exact XP| exact C|]. rewrite LNodeCells_size.
    destruct (FieldsC_lnode_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P0 & _ & R)].
    - split; [left; lia| eapply XSUB; [exact XB| lia| cbn; lia]].
    - pose proof (esize_ge d). eapply ESUB; [exact Ld| lia| cbn; lia]. }
  split.
  { intros e d Ld. eapply xpres_rw_cells; [exact XP| exact (EC e d Ld)|]. rewrite ValCells_size.
    eapply ESUB; [exact Ld| lia| lia]. }
  split; [exact OK|]. split; [exact SO|]. split; [exact DL|]. split; [exact SL|]. split; [exact LE'|].
  split; [exact EOK|]. split; [exact HH|]. split; [exact HB| exact AL].
Qed.

