Definition pd_seg1_post (sp gp tp a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0 t1 t2 t3 t4 t5 t6 ra s0 s1 : word) (P lo : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk,
    ms' = MS (mkR (wz PD_RA1) (wz (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz P) (wz (P + 80)) (wz (P + 168)) (wz (P + 176)) (wz (P + 304))
                  a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz P_MBUF_DTOR) fc None m' (seg_rom usegs)
    /\ munch [(bv_unsigned sp + -32, bv_unsigned sp); (P, P + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells usegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra]
    /\ rw_cells usegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells usegs m' (P + 288) [C8 (wz 0)] /\ rw_cells usegs m' (P + 336) [C8 (wz 0)].

